SELECT * FROM cs_sessions


        AND status = #{status}


        AND user_type = #{userType}


        AND (user_name LIKE CONCAT('%', #{keyword}, '%') OR user_phone LIKE CONCAT('%', #{keyword}, '%') OR session_no LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY last_message_at DESC, id DESC

