UPDATE cs_sessions
SET status = 'PROCESSING', agent_id = #{agentId}, agent_name = #{agentName}
WHERE id = #{id}

UPDATE cs_sessions
SET status = 'CLOSED', closed_at = NOW()
WHERE id = #{id}

UPDATE cs_sessions
SET last_message = #{lastMessage}, last_message_at = NOW()
WHERE id = #{id}
